// ==========================================
// 1. BULLETPROOF JAPANESE VOICE ENGINE
// ==========================================
let currentAudioPlayer = null;

function cleanJapaneseText(text) {
    if (!text) return '';
    let t = text.split('/')[0];
    return t
        .replace(/\(.*?\)/g, '')
        .replace(/（.*?）/g, '')
        .replace(/\[.*?\]/g, '')
        .replace(/【.*?】/g, '')
        .replace(/[a-zA-Z]/g, '')
        .replace(/[～〜・→➔*#_]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
}

