function renderCountGrid() {
    const grid = document.getElementById('countGrid');
    grid.innerHTML = countData.map(c => `
        <div class="count-card ${c.isSpecial ? 'highlight' : ''}" onclick="speakText('${c.reading}')">
            ${c.tag ? `<span class="count-badge">${c.tag}</span>` : ''}
            <div class="count-num jp-text">${c.num}</div>
            <div class="count-reading jp-text">${c.reading}</div>
            <div class="count-romaji">${c.romaji} 🔊</div>
        </div>
    `).join('');
}

